CREATE TABLE platform_user (id BIGINT PRIMARY KEY, username VARCHAR(128) NOT NULL, password_hash VARCHAR(255) NOT NULL, status VARCHAR(32) NOT NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), UNIQUE KEY uk_username(username));
CREATE TABLE tenant_user_membership (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, user_id BIGINT NOT NULL, employee_no VARCHAR(64) NULL, display_name VARCHAR(128) NULL, primary_org_id BIGINT NULL, status VARCHAR(32) NOT NULL, created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), version INT NOT NULL DEFAULT 0, UNIQUE KEY uk_membership(tenant_id,user_id), KEY idx_membership_org(tenant_id,primary_org_id,status));
CREATE TABLE role (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, role_code VARCHAR(64) NOT NULL, role_name VARCHAR(128) NOT NULL, status VARCHAR(32) NOT NULL, risk_level INT NOT NULL DEFAULT 1, UNIQUE KEY uk_role(tenant_id,role_code));
CREATE TABLE permission (id BIGINT PRIMARY KEY, permission_code VARCHAR(128) NOT NULL, permission_name VARCHAR(128) NOT NULL, module_code VARCHAR(64) NOT NULL, UNIQUE KEY uk_perm(permission_code));
CREATE TABLE role_permission (role_id BIGINT NOT NULL, permission_id BIGINT NOT NULL, PRIMARY KEY(role_id,permission_id));
CREATE TABLE user_role (tenant_id BIGINT NOT NULL, membership_id BIGINT NOT NULL, role_id BIGINT NOT NULL, PRIMARY KEY(tenant_id,membership_id,role_id));
CREATE TABLE organization_unit (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, parent_id BIGINT NULL, org_code VARCHAR(64) NOT NULL, org_name VARCHAR(128) NOT NULL, org_type VARCHAR(32) NOT NULL, path VARCHAR(1024) NOT NULL, level_no INT NOT NULL, status VARCHAR(32) NOT NULL, UNIQUE KEY uk_org(tenant_id,org_code), KEY idx_org_parent(tenant_id,parent_id));
CREATE TABLE management_team (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, team_code VARCHAR(64) NOT NULL, team_name VARCHAR(128) NOT NULL, status VARCHAR(32) NOT NULL, UNIQUE KEY uk_team(tenant_id,team_code));
CREATE TABLE management_team_member (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, team_id BIGINT NOT NULL, membership_id BIGINT NOT NULL, role_code VARCHAR(64) NULL, effective_from DATETIME(3) NOT NULL, effective_to DATETIME(3) NULL, status VARCHAR(32) NOT NULL, KEY idx_team_member(tenant_id,team_id,status));
CREATE TABLE team_resource_relation (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, team_id BIGINT NOT NULL, resource_type VARCHAR(32) NOT NULL, resource_id BIGINT NOT NULL, relation_type VARCHAR(32) NOT NULL, effective_from DATETIME(3) NOT NULL, effective_to DATETIME(3) NULL, KEY idx_team_res(tenant_id,resource_type,resource_id));
CREATE TABLE resource_acl (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, principal_type VARCHAR(32) NOT NULL, principal_id BIGINT NOT NULL, resource_type VARCHAR(32) NOT NULL, resource_id BIGINT NOT NULL, permission_code VARCHAR(128) NOT NULL, effective_from DATETIME(3) NOT NULL, effective_to DATETIME(3) NULL, KEY idx_acl_resource(tenant_id,resource_type,resource_id));
CREATE TABLE ownership_history (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, business_type VARCHAR(32) NOT NULL, business_id BIGINT NOT NULL, old_owner_id BIGINT NULL, new_owner_id BIGINT NULL, reason VARCHAR(512) NULL, changed_by BIGINT NOT NULL, changed_at DATETIME(3) NOT NULL, KEY idx_owner_hist(tenant_id,business_type,business_id,changed_at));
